@slots literal
{
  "note": "I compare the price per 100 washes after adding delivery. I ignore scent. If the difference per 100 is under 5, I choose the lighter box.",
  "A": {
    "price": 49,
    "washes": 10,
    "delivery": 4,
    "kg": 4
  },
  "B": {
    "price": 44,
    "washes": 8,
    "delivery": 14,
    "kg": 3
  }
}

@answer jsEval
const slots = $slots;
probe(Number.isInteger(slots.A.price) && slots.A.price > 0, "the price of the lighter box must be a positive whole number");
probe(Number.isInteger(slots.B.price) && slots.B.price > 0, "the price of the heavier box must be a positive whole number");
probe(Number.isInteger(slots.A.washes) && slots.A.washes > 0, "the lighter box must have at least one wash");
probe(Number.isInteger(slots.B.washes) && slots.B.washes > 0, "the heavier box must have at least one wash");
probe(slots.A.delivery >= 0, "the delivery cost of the lighter box must be a whole number or zero");
probe(slots.B.delivery >= 0, "the delivery cost of the heavier box must be a whole number or zero");
probe(Number.isInteger(slots.A.kg) && slots.A.kg > 0, "the lighter box must weigh at least one kilogram");
probe(Number.isInteger(slots.B.kg) && slots.B.kg > 0, "the heavier box must weigh at least one kilogram");
const A = slots.A;
const B = slots.B;
probe(A.delivery + A.washes * A.price / 100 < B.delivery + B.washes * B.price / 100, "the lighter box must cost less per wash than the heavier box");
probe(B.delivery + B.washes * B.price / 100 - A.delivery - A.washes * A.price / 100 < 5, "the difference in price must be under five cents");
const lighter = A.delivery + A.washes * A.price / 100;
const heavier = B.delivery + B.washes * B.price / 100;
probe(lighter === heavier || (lighter > heavier && slots.A.kg < slots.B.kg), "the boxes must cost the same per wash if they weigh the same");
return "The lighter box costs $" + lighter.toFixed(2) + ". The decision is: " + (lighter <= heavier ? "choose the lighter box" : "choose the heavier box");

