    },
    {
      "name": "insect bite months",
      "units": "number of months"
    }
  ],
  "cause": "hot months",
  "conclusion": "Ice cream causes bites."
}

@answer jsEval
const slots = $slots;
probe(Array.isArray(slots.series) && slots.series.length > 0, "the statement must name two series");
probe(slots.series.every((series) => Array.isArray(series) && series.length === 2), "every series must name a cause and an effect");
probe(slots.series.some((series) => series.units !== undefined), "every series must state the units of its measurement");
probe(slots.series.every((series) => slots.series.every((unit) => unit !== undefined)), "every series must name every unit");
probe(Array.isArray(slots.months) && slots.months.length > 0, "the statement must name three months");
probe(slots.months.every((month) => Array.isArray(month) && month.length === 2), "every month must name a cause and an effect");
probe(slots.months.some((month) => month.units !== undefined), "every month must state the units of its measurement");
probe(slots.months.every((month) => slots.months.every((unit) => unit !== undefined)), "every month must name every unit");
const series = slots.series;
const months = slots.months;
probe(series.length === months.length, "the statement must name a cause and an effect for each month");
probe(months.some((month) => month.name === slots.cause), "the statement must state the cause of the first month");
probe(months.every((month) => series.some((series) => month.name === series.name)), "every month must name one of the two named causes");
const units = new Set();
for (const unit of months.flatMap((month) => month.units)) {
  probe(unit !== undefined, "the statement must state every unit of measurement");
  units.add(unit);
}
probe(units.size > 1, "the statement must name at least two different units");
return "The text does not state the cause of the second month. Without a mechanism from the text we do not declare the cause.";

