@slots literal
{
  "urn": "6 white, 2 red",
  "draws": 8,
  "obligatory": "a red is now obligatory, because 2/8 of 8 is 2"
}

@answer jsEval
const slots = $slots;
probe(Number.isInteger(slots.draws) && slots.draws > 0, "the number of draws must be a positive whole number");
probe(slots.urn.includes("6 white") && slots.urn.includes("2 red"), "the urn must contain exactly six white and two red balls");
const total = slots.urn.split(/\s+/).reduce((sum, word) => sum + (word === "white" ? 1 : 0), 0);
probe(total === 8, "the urn must contain exactly eight balls");
probe(slots.draws % total === 0, "the number of draws must be a multiple of the urn's ball count");
const red = slots.urn.split(/\s+/).reduce((sum, word) => sum + (word === "red" ? 1 : 0), 0);
probe(red > 0 && red < total, "the urn must contain at least one red and no more than six white balls");
probe(slots.obligatory.includes("2/8"), "the statement must refer to the probability of drawing a red ball");
const sought = slots.urn.split(/\s+/).reduce((sum, word) => sum + (word === "red" ? 1 : 0), 0);
probe(sought > 0 && sought < total, "the urn must contain at least one red and no more than six white balls");
probe(Number.isInteger(slots.draws / sought) && slots.draws % sought === 0, "the number of draws must be a multiple of the urn's red ball count");
const probability = slots.urn.split(/\s+/).reduce((sum, word) => sum + (word === "red" ? 1 : 0), 0);
probe(probability > 0 && probability < total, "the urn must contain at least one red and no more than six white balls");
return `The probability of drawing a red ball on one draw is ${probability / total}. The statement refers to the probability of drawing ${sought} red balls in ${slots.draws} draws. Since ${sought} is less than ${total}, the statement does not oblige.`;

